import re
from decimal import Decimal


class InsufficientFunds(Exception):
    pass


class Ledger:
    _pattern = re.compile(r'^[0-9]+(?:\.[0-9]{1,2})?$')

    def __init__(self, overdraft_limit='0.00'):
        self._validate_amount(overdraft_limit, allow_zero=True)
        self._overdraft_limit = Decimal(overdraft_limit)
        self._balance = Decimal('0')
        self._history = []

    @classmethod
    def _validate_amount(cls, amount, allow_zero=False):
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not cls._pattern.match(amount):
            raise ValueError("invalid amount format")
        value = Decimal(amount)
        if not allow_zero and value == 0:
            raise ValueError("amount must be non-zero")
        return value

    @staticmethod
    def _format(value):
        s = f"{value:.2f}"
        if s == '-0.00':
            s = '0.00'
        return s

    def deposit(self, amount):
        value = self._validate_amount(amount, allow_zero=False)
        self._balance += value
        self._history.append(('deposit', self._format(value)))

    def withdraw(self, amount):
        value = self._validate_amount(amount, allow_zero=False)
        if self._balance - value < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance -= value
        self._history.append(('withdraw', self._format(value)))
        if self._balance < 0:
            fee = Decimal('1.50')
            self._balance -= fee
            self._history.append(('fee', self._format(fee)))

    def balance(self):
        return self._format(self._balance)

    def history(self):
        return list(self._history)
