import heapq


def _validate(meetings, k):
    if not isinstance(k, int) or isinstance(k, bool) or k < 1:
        raise ValueError("k must be an int (not bool) and >= 1")

    if not isinstance(meetings, list):
        raise ValueError("meetings must be a list")

    for item in meetings:
        if not isinstance(item, (list, tuple)) or len(item) != 2:
            raise ValueError("each meeting must be a pair of int endpoints")
        start, end = item
        if (
            not isinstance(start, int)
            or isinstance(start, bool)
            or not isinstance(end, int)
            or isinstance(end, bool)
        ):
            raise ValueError("meeting endpoints must be ints (not bool/float)")
        if start >= end:
            raise ValueError("meeting start must be less than end")


def assign_rooms(meetings: list[tuple[int, int]], k: int) -> list[tuple[int, int, int]]:
    _validate(meetings, k)

    n = len(meetings)
    if n == 0:
        return []

    indexed = [
        (meetings[i][0], meetings[i][1], i, meetings[i][1] - meetings[i][0])
        for i in range(n)
    ]
    indexed.sort(key=lambda x: (x[0], x[2]))

    available = list(range(k))
    heapq.heapify(available)
    busy = []  # min-heap of (release_time, room_id)
    assignments = [None] * n

    for start, end, original_index, duration in indexed:
        # Free all rooms whose release_time <= start
        while busy and busy[0][0] <= start:
            release_time, room_id = heapq.heappop(busy)
            heapq.heappush(available, room_id)

        if available:
            actual_start = start
            room_id = heapq.heappop(available)
        else:
            earliest_release = busy[0][0]
            # Free all rooms with the earliest release time
            while busy and busy[0][0] == earliest_release:
                release_time, room_id = heapq.heappop(busy)
                heapq.heappush(available, room_id)
            actual_start = earliest_release
            room_id = heapq.heappop(available)

        actual_end = actual_start + duration
        heapq.heappush(busy, (actual_end, room_id))
        assignments[original_index] = (room_id, actual_start, actual_end)

    return assignments


def busiest_room(meetings: list[tuple[int, int]], k: int) -> int:
    _validate(meetings, k)

    n = len(meetings)
    if n == 0:
        return 0

    assignments = assign_rooms(meetings, k)
    counts = [0] * k
    for room_id, _, _ in assignments:
        counts[room_id] += 1

    best_room = 0
    best_count = counts[0]
    for room_id in range(1, k):
        if counts[room_id] > best_count:
            best_count = counts[room_id]
            best_room = room_id

    return best_room
