def merge(intervals):
    """
    Return a sorted list of disjoint half-open intervals [start, end) as tuples.
    Overlapping and touching intervals are merged. Empty intervals are dropped.
    Invalid intervals (start > end) raise ValueError. Inputs are not modified.
    """
    if not intervals:
        return []

    parsed = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = iv
        if start > end:
            raise ValueError("Interval start must not be greater than end")
        if start == end:
            continue
        parsed.append((start, end))

    if not parsed:
        return []

    parsed.sort(key=lambda x: x[0])

    merged = [parsed[0]]
    for start, end in parsed[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))

    return merged


def subtract(a, b):
    """
    Return the points in interval list a that are not in interval list b,
    as a merged, sorted list of tuple intervals. Inputs are not modified.
    """
    a_merged = merge(a)
    b_merged = merge(b)

    result = []
    b_idx = 0
    n_b = len(b_merged)

    for a_start, a_end in a_merged:
        current_start = a_start
        current_end = a_end

        while b_idx < n_b and b_merged[b_idx][1] <= current_start:
            b_idx += 1

        i = b_idx
        while i < n_b and b_merged[i][0] < current_end:
            b_start, b_end = b_merged[i]

            if b_start > current_start:
                result.append((current_start, b_start))

            current_start = max(current_start, b_end)
            if current_start >= current_end:
                break
            i += 1

        if current_start < current_end:
            result.append((current_start, current_end))

    return result


def total_length(intervals):
    """
    Return the total length covered by the union of the half-open intervals.
    """
    merged = merge(intervals)
    return sum(end - start for start, end in merged)
