def render(template: str, values: dict) -> str:
    out = []
    i = 0
    n = len(template)
    while i < n:
        # Find the next backslash or '{{'
        bs = template.find('\\', i)
        ph = template.find('{{', i)
        if bs == -1:
            nxt = ph
        elif ph == -1:
            nxt = bs
        else:
            nxt = bs if bs < ph else ph

        if nxt == -1:
            # No more escapes or placeholders
            out.append(template[i:])
            break

        # Append literal slice before the special token
        out.append(template[i:nxt])

        if nxt == bs:
            # Backslash handling
            if nxt + 1 < n and template[nxt + 1] == '\\':
                out.append('\\')
                i = nxt + 2
            elif nxt + 2 < n and template[nxt + 1:nxt + 3] == '{{':
                out.append('{{')
                i = nxt + 3
            else:
                out.append('\\')
                i = nxt + 1
        else:
            # Placeholder start '{{'
            close = template.find('}}', nxt + 2)
            if close == -1:
                raise ValueError(f'unclosed placeholder at {nxt}')

            body = template[nxt + 2:close]
            pipe = body.find('|')
            if pipe == -1:
                key_part = body
                default = None
            else:
                key_part = body[:pipe]
                default = body[pipe + 1:]

            # Strip only spaces (ASCII 32), not tabs/newlines
            key = key_part.strip(' ')
            if default is None:
                default_text = None
            else:
                default_text = default.strip(' ')

            # Validate key segments
            if key == '':
                # Empty key is allowed syntactically, but segment validation fails
                raise ValueError(f'bad key: {key}')
            segments = key.split('.')
            for seg in segments:
                if not seg:
                    raise ValueError(f'bad key: {key}')
                if not (seg[0].isalpha() or seg[0] == '_'):
                    raise ValueError(f'bad key: {key}')
                for ch in seg[1:]:
                    if not (ch.isalnum() or ch == '_'):
                        raise ValueError(f'bad key: {key}')

            # Resolve nested key
            cur = values
            missing = False
            for seg in segments:
                if not isinstance(cur, dict) or seg not in cur:
                    missing = True
                    break
                cur = cur[seg]
            if not missing and cur is None:
                missing = True

            if missing:
                if default_text is not None:
                    out.append(default_text)
                else:
                    raise KeyError(f'missing: {key}')
            else:
                if cur is True:
                    out.append('true')
                elif cur is False:
                    out.append('false')
                else:
                    out.append(str(cur))

            i = close + 2

    return ''.join(out)
