def parse_ini(text: str) -> dict:
    result: dict[str, dict[str, str]] = {}
    current_section = ''
    current_key: tuple[str, str] | None = None

    for line_no, raw_line in enumerate(text.split('\n'), start=1):
        line = raw_line[:-1] if raw_line.endswith('\r') else raw_line

        if line.strip() == '':
            current_key = None
            continue

        stripped = line.lstrip()
        first_non_ws = stripped[0]

        if first_non_ws in ';#':
            continue

        if line[0] in ' \t':
            if current_key is None:
                raise ValueError(f'line {line_no}: continuation line without a key to continue')
            section, key = current_key
            value = result[section][key]
            appended = stripped
            if value == '':
                result[section][key] = appended
            else:
                result[section][key] = value + ' ' + appended
            continue

        stripped_full = line.strip()
        if stripped_full.startswith('[') and stripped_full.endswith(']'):
            name = stripped_full[1:-1].strip().lower()
            current_section = name
            result.setdefault(current_section, {})
            current_key = None
            continue

        eq_index = line.find('=')
        if eq_index == -1:
            raise ValueError(f'line {line_no}: missing "=" in key line')
        key_part = line[:eq_index].strip()
        value_part = line[eq_index + 1:].strip()
        if key_part == '':
            raise ValueError(f'line {line_no}: empty key')

        key = key_part.lower()
        result.setdefault(current_section, {})
        if key in result[current_section]:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')
        result[current_section][key] = value_part
        current_key = (current_section, key)

    for section in result:
        for key, value in result[section].items():
            if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                result[section][key] = value[1:-1]

    return result
