import copy


def _decode_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("Pointer must start with '/' or be empty")
    raw_tokens = pointer[1:].split("/")
    decoded = []
    for token in raw_tokens:
        out = []
        i = 0
        while i < len(token):
            ch = token[i]
            if ch == "~":
                if i + 1 >= len(token):
                    raise ValueError("Unescaped '~' at end of token")
                nxt = token[i + 1]
                if nxt == "0":
                    out.append("~")
                    i += 2
                elif nxt == "1":
                    out.append("/")
                    i += 2
                else:
                    raise ValueError("Invalid '~' escape in token")
            else:
                out.append(ch)
                i += 1
        decoded.append("".join(out))
    return decoded


def _is_valid_index(token, length, allow_append=False):
    if token == "-":
        return allow_append, None
    if not token:
        return False, None
    if token[0] == "0":
        if token == "0":
            return True, 0
        return False, None
    if not token.isdigit():
        return False, None
    idx = int(token)
    if allow_append:
        if idx < 0 or idx > length:
            return False, None
        if idx == length:
            return True, idx
    if idx < 0 or idx >= length:
        return False, None
    return True, idx


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            ok, idx = _is_valid_index(token, len(current), allow_append=False)
            if not ok:
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    return current


def set_value(doc, pointer, value):
    if pointer == "":
        return copy.deepcopy(value)
    tokens = _decode_pointer(pointer)
    new_doc = copy.deepcopy(doc)
    current = new_doc
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            ok, idx = _is_valid_index(token, len(current), allow_append=False)
            if not ok:
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)
    last = tokens[-1]
    if isinstance(current, dict):
        current[last] = copy.deepcopy(value)
    elif isinstance(current, list):
        ok, idx = _is_valid_index(last, len(current), allow_append=True)
        if not ok:
            raise KeyError(last)
        if idx == len(current) or last == "-":
            current.append(copy.deepcopy(value))
        else:
            current[idx] = copy.deepcopy(value)
    else:
        raise KeyError(last)
    return new_doc


def escape_token(token):
    return token.replace("~", "~0").replace("/", "~1")
