def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an int >= 2")

    words = text.split()
    if not words:
        return []

    result = []
    current = ""

    for word in words:
        if len(word) > width:
            if current:
                result.append(current)
                current = ""
            chunk_size = width - 1
            while len(word) > width:
                result.append(word[:chunk_size] + "-")
                word = word[chunk_size:]
            current = word
        else:
            if current:
                if len(current) + 1 + len(word) <= width:
                    current += " " + word
                else:
                    result.append(current)
                    current = word
            else:
                current = word

    if current:
        result.append(current)

    return result
