from collections import deque
import math


def _validate_limit(limit):
    if isinstance(limit, bool):
        raise ValueError("limit must not be a bool")
    if not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float")
    if isinstance(limit, float) and math.isnan(limit):
        raise ValueError("limit must not be NaN")
    if limit < 0:
        raise ValueError("limit must not be negative")


def _validate_value(value):
    if isinstance(value, bool):
        raise TypeError("values must contain ints or floats, not bool")
    if not isinstance(value, (int, float)):
        raise TypeError("values must contain ints or floats")
    if isinstance(value, float) and math.isnan(value):
        raise ValueError("values must not contain NaN")


def longest_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return (0, 0)

    for v in values:
        _validate_value(v)

    max_deque = deque()
    min_deque = deque()
    left = 0
    best_len = 0
    best_start = 0

    for right in range(n):
        v = values[right]
        while max_deque and values[max_deque[-1]] <= v:
            max_deque.pop()
        max_deque.append(right)
        while min_deque and values[min_deque[-1]] >= v:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and min_deque and values[max_deque[0]] - values[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best_len:
            best_len = window_len
            best_start = left

    return (best_start, best_start + best_len)


def count_calm(values, limit):
    _validate_limit(limit)

    n = len(values)
    if n == 0:
        return 0

    for v in values:
        _validate_value(v)

    max_deque = deque()
    min_deque = deque()
    left = 0
    total = 0

    for right in range(n):
        v = values[right]
        while max_deque and values[max_deque[-1]] <= v:
            max_deque.pop()
        max_deque.append(right)
        while min_deque and values[min_deque[-1]] >= v:
            min_deque.pop()
        min_deque.append(right)

        while max_deque and min_deque and values[max_deque[0]] - values[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        total += right - left + 1

    return total
