import heapq
from typing import Dict


class MedianTracker:
    def __init__(self, prefer_high: bool = False):
        self.prefer_high = prefer_high
        # max-heap for the lower half (store negatives)
        self._low: list[int] = []
        # min-heap for the upper half
        self._high: list[int] = []
        # lazy deletion counters
        self._delayed_low: Dict[int, int] = {}
        self._delayed_high: Dict[int, int] = {}
        # effective sizes (excluding lazily deleted elements)
        self._low_size = 0
        self._high_size = 0
        # total number of stored elements
        self._total = 0

    def _validate_int(self, x) -> int:
        if type(x) is not int:
            raise TypeError("value must be int")
        return x

    def _prune_low(self) -> None:
        while self._low:
            val = -self._low[0]
            if self._delayed_low.get(val, 0):
                heapq.heappop(self._low)
                self._delayed_low[val] -= 1
                if self._delayed_low[val] == 0:
                    del self._delayed_low[val]
            else:
                break

    def _prune_high(self) -> None:
        while self._high:
            val = self._high[0]
            if self._delayed_high.get(val, 0):
                heapq.heappop(self._high)
                self._delayed_high[val] -= 1
                if self._delayed_high[val] == 0:
                    del self._delayed_high[val]
            else:
                break

    def _make_balance(self) -> None:
        # low may have at most one more element than high
        if self._low_size > self._high_size + 1:
            self._prune_low()
            val = -heapq.heappop(self._low)
            self._low_size -= 1
            heapq.heappush(self._high, val)
            self._high_size += 1
            self._prune_low()
        elif self._low_size < self._high_size:
            self._prune_high()
            val = heapq.heappop(self._high)
            self._high_size -= 1
            heapq.heappush(self._low, -val)
            self._low_size += 1
            self._prune_high()

    def add(self, x) -> None:
        x = self._validate_int(x)
        if not self._low or x <= -self._low[0]:
            heapq.heappush(self._low, -x)
            self._low_size += 1
        else:
            heapq.heappush(self._high, x)
            self._high_size += 1
        self._total += 1
        self._make_balance()

    def remove(self, x) -> None:
        x = self._validate_int(x)
        if x not in self:
            raise ValueError("not present")
        if self._low and x <= -self._low[0]:
            self._delayed_low[x] = self._delayed_low.get(x, 0) + 1
            self._low_size -= 1
            if x == -self._low[0]:
                self._prune_low()
        else:
            self._delayed_high[x] = self._delayed_high.get(x, 0) + 1
            self._high_size -= 1
            if self._high and x == self._high[0]:
                self._prune_high()
        self._total -= 1
        self._make_balance()

    def median(self) -> int:
        if self._total == 0:
            raise LookupError("median is undefined for empty MedianTracker")
        self._prune_low()
        self._prune_high()
        if self._total % 2 == 1:
            return -self._low[0]
        if self.prefer_high:
            return self._high[0]
        return -self._low[0]

    def __len__(self) -> int:
        return self._total

    def __contains__(self, x) -> bool:
        self._validate_int(x)
        count = 0
        for heap_list, delayed in ((self._low, self._delayed_low),
                                   (self._high, self._delayed_high)):
            for val in heap_list:
                real = -val if heap_list is self._low else val
                if real == x:
                    count += 1
            count -= delayed.get(x, 0)
        return count > 0
