_ROMAN_SYMBOLS = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)


def to_roman(n: int) -> str:
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")

    parts = []
    for value, symbol in _ROMAN_SYMBOLS:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def from_roman(s: str) -> int:
    if not isinstance(s, str):
        raise TypeError("s must be a str")

    total = 0
    index = 0
    length = len(s)
    for value, symbol in _ROMAN_SYMBOLS:
        sym_len = len(symbol)
        while index + sym_len <= length and s[index:index + sym_len] == symbol:
            total += value
            index += sym_len

    if index != length or total < 1 or total > 3999:
        raise ValueError("s is not a canonical Roman numeral")

    if to_roman(total) != s:
        raise ValueError("s is not a canonical Roman numeral")

    return total


def is_roman(s: Any) -> bool:
    try:
        from_roman(s)
        return True
    except Exception:
        return False
