import math


class TokenBucket:
    def __init__(self, capacity, refill_rate, clock):
        if capacity <= 0:
            raise ValueError("capacity must be > 0")
        if refill_rate < 0:
            raise ValueError("refill_rate must be >= 0")

        self.capacity = capacity
        self.refill_rate = refill_rate
        self.clock = clock

        self._tokens = capacity
        self._last_refill = clock()

    def _refill(self):
        now = self.clock()
        if now > self._last_refill:
            self._tokens = min(
                self.capacity,
                self._tokens + (now - self._last_refill) * self.refill_rate,
            )
            self._last_refill = now

    @property
    def tokens(self):
        self._refill()
        return self._tokens

    def try_consume(self, n=1):
        if n <= 0 or n > self.capacity:
            raise ValueError("n must satisfy 0 < n <= capacity")

        self._refill()
        if self._tokens >= n:
            self._tokens -= n
            return True
        return False

    def wait_time(self, n=1):
        if n <= 0 or n > self.capacity:
            raise ValueError("n must satisfy 0 < n <= capacity")

        self._refill()
        if self._tokens >= n:
            return 0.0
        if self.refill_rate == 0:
            return math.inf
        return (n - self._tokens) / self.refill_rate
