def expand_field(field, lo, hi):
    if field == "":
        raise ValueError("invalid cron field: empty")

    items = field.split(",")
    result_set = set()

    for item in items:
        item = item.strip()
        if item == "":
            raise ValueError("invalid cron field: empty item")

        base = item
        step = 1
        if "/" in item:
            parts = item.split("/")
            if len(parts) != 2:
                raise ValueError("invalid cron field: malformed step")
            base, step_str = parts
            if not step_str.isdigit() or step_str == "":
                raise ValueError("invalid cron field: malformed step")
            step = int(step_str)
            if step == 0:
                raise ValueError("invalid cron field: step cannot be zero")

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            range_parts = base.split("-")
            if len(range_parts) != 2:
                raise ValueError("invalid cron field: malformed range")
            a_str, b_str = range_parts
            if not a_str.isdigit() or not b_str.isdigit():
                raise ValueError("invalid cron field: non-digit in range")
            a, b = int(a_str), int(b_str)
            if a > b:
                raise ValueError("invalid cron field: range start greater than end")
            if a < lo or b > hi:
                raise ValueError("invalid cron field: value out of range")
            start, end = a, b
        else:
            if not base.isdigit():
                raise ValueError("invalid cron field: non-digit value")
            n = int(base)
            if n < lo or n > hi:
                raise ValueError("invalid cron field: value out of range")
            start, end = n, hi

        if start < lo or end > hi:
            raise ValueError("invalid cron field: value out of range")

        for value in range(start, end + 1, step):
            result_set.add(value)

    return sorted(result_set)


def _parse_expr(expr):
    if not isinstance(expr, str):
        raise ValueError("invalid cron expression: must be string")
    fields = expr.strip().split()
    if len(fields) != 2:
        raise ValueError("invalid cron expression: must have exactly two fields")
    minute_field, hour_field = fields
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    return minute in minutes and hour in hours


def next_match(expr, hour, minute):
    minutes, hours = _parse_expr(expr)

    total_minutes = hour * 60 + minute
    for offset in range(1, 1441):
        next_total = (total_minutes + offset) % 1440
        next_hour = next_total // 60
        next_minute = next_total % 60
        if next_minute in minutes and next_hour in hours:
            return (next_hour, next_minute)

    raise ValueError("invalid cron expression: no matching time found")
