from fractions import Fraction
from typing import Union

def evaluate(expr: str) -> Union[int, Fraction]:
    tokens = _tokenize(expr)
    if not tokens:
        raise ValueError("empty input")
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def consume(expected=None):
        nonlocal pos
        tok = tokens[pos]
        if expected is not None and tok != expected:
            raise ValueError(f"expected {expected!r}")
        pos += 1
        return tok

    def parse_expr():
        value = parse_term()
        while True:
            nxt = peek()
            if nxt == '+' or nxt == '-':
                op = consume()
                rhs = parse_term()
                if op == '+':
                    value = value + rhs
                else:
                    value = value - rhs
            else:
                break
        return value

    def parse_term():
        value = parse_unary()
        while True:
            nxt = peek()
            if nxt == '*' or nxt == '/':
                op = consume()
                rhs = parse_unary()
                if op == '*':
                    value = value * rhs
                else:
                    value = value / rhs
            else:
                break
        return value

    def parse_unary():
        if peek() == '-':
            consume()
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            consume()
            exponent = parse_unary()
            return _power(base, exponent)
        return base

    def parse_atom():
        nxt = peek()
        if nxt is None:
            raise ValueError("missing operand")
        if isinstance(nxt, int):
            consume()
            return Fraction(nxt)
        if nxt == '(':
            consume('(')
            value = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            consume(')')
            return value
        raise ValueError("unexpected token")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("leftover tokens")
    if result.denominator == 1:
        return result.numerator
    return result


def _tokenize(expr: str):
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c in ' \t':
            i += 1
            continue
        if c in '+-*/^()':
            tokens.append(c)
            i += 1
            continue
        if c.isdigit():
            start = i
            while i < len(expr) and expr[i].isdigit():
                i += 1
            tokens.append(int(expr[start:i]))
            continue
        raise ValueError(f"invalid character {c!r}")
    return tokens


def _power(base: Fraction, exponent: Fraction) -> Fraction:
    if exponent.denominator != 1:
        raise ValueError("exponent must be a whole number")
    exp = exponent.numerator
    if base == 0:
        if exp > 0:
            return Fraction(0)
        if exp == 0:
            return Fraction(1)
        raise ZeroDivisionError("0 to a negative power")
    if exp < 0:
        return Fraction(1, 1) / (base ** (-exp))
    return base ** exp
