import bisect


def _validate_intervals(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")
    for item in intervals:
        if not isinstance(item, (tuple, list)) or len(item) != 3:
            raise TypeError("each interval must be a length-3 sequence")
        start, end, weight = item
        if type(start) is not int or type(end) is not int or type(weight) is not int:
            raise TypeError("start, end, weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals: list[tuple[int, int, int]]) -> tuple[int, int]:
    _validate_intervals(intervals)

    n = len(intervals)
    if n == 0:
        return (0, 0)

    sorted_intervals = sorted(intervals, key=lambda x: x[1])
    ends = [interval[1] for interval in sorted_intervals]

    # dp[i] = (best_total_weight, interval_count) using first i intervals
    dp = [(0, 0)] * (n + 1)

    for i in range(1, n + 1):
        start, end, weight = sorted_intervals[i - 1]
        p = bisect.bisect_left(ends, start)
        candidate_take = (dp[p][0] + weight, dp[p][1] + 1)
        candidate_skip = dp[i - 1]

        if candidate_take[0] > candidate_skip[0]:
            dp[i] = candidate_take
        elif candidate_take[0] < candidate_skip[0]:
            dp[i] = candidate_skip
        else:
            # equal total weight: choose the one with fewer intervals
            if candidate_take[1] < candidate_skip[1]:
                dp[i] = candidate_take
            else:
                dp[i] = candidate_skip

    result = dp[n]
    if result[0] <= 0:
        return (0, 0)
    return result


def max_parallel(intervals: list[tuple[int, int, int]]) -> int:
    _validate_intervals(intervals)

    if not intervals:
        return 0

    events = []
    for start, end, _weight in intervals:
        events.append((start, 1))
        events.append((end, -1))

    # sort by time; for same time, process ends (-1) before starts (1)
    events.sort(key=lambda x: (x[0], x[1]))

    current = 0
    maximum = 0
    for _time, delta in events:
        current += delta
        if current > maximum:
            maximum = current

    return maximum
