class Scheduler:
    def __init__(self):
        self._tasks = {}  # name -> task dict
        self._insertion_counter = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")

        after_set = set(after)
        missing = after_set - self._tasks.keys()
        if missing:
            raise KeyError(next(iter(missing)))

        self._tasks[name] = {
            "priority": priority,
            "insertion_order": self._insertion_counter,
            "status": "pending",
            "after": after_set,
        }
        self._insertion_counter += 1

    def next(self):
        ready = [
            (info["priority"], info["insertion_order"], name)
            for name, info in self._tasks.items()
            if info["status"] == "pending"
            and all(self._tasks[dep]["status"] == "completed" for dep in info["after"])
        ]

        if not ready:
            return None

        ready.sort(key=lambda x: (-x[0], x[1]))
        _, _, name = ready[0]
        self._tasks[name]["status"] = "running"
        return name

    def complete(self, name):
        if name not in self._tasks:
            raise KeyError(name)

        status = self._tasks[name]["status"]
        if status != "running":
            raise ValueError(f"Task {name!r} is not running (status: {status})")

        self._tasks[name]["status"] = "completed"

    def remaining(self):
        return sum(1 for info in self._tasks.values() if info["status"] != "completed")
