import re

_VERSION_RE = re.compile(
    r"^(?i)[vV]?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def parse_version(text: str) -> tuple[int, int, int, tuple, str | None]:
    match = _VERSION_RE.match(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")

    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))

    prerelease_raw = match.group(4)
    build_raw = match.group(5)

    prerelease: list = []
    if prerelease_raw is not None:
        for identifier in prerelease_raw.split("."):
            if identifier.isdigit():
                if len(identifier) > 1 and identifier[0] == "0":
                    raise ValueError(f"invalid version: {text!r}")
                prerelease.append(int(identifier))
            else:
                if not identifier:
                    raise ValueError(f"invalid version: {text!r}")
                prerelease.append(identifier)

    build: str | None = build_raw if build_raw is not None else None

    return (major, minor, patch, tuple(prerelease), build)


def _compare_prerelease(pre_a: tuple, pre_b: tuple) -> int:
    if pre_a == pre_b:
        return 0

    len_a = len(pre_a)
    len_b = len(pre_b)
    min_len = min(len_a, len_b)

    for i in range(min_len):
        id_a = pre_a[i]
        id_b = pre_b[i]
        if isinstance(id_a, int) and isinstance(id_b, int):
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        elif isinstance(id_a, str) and isinstance(id_b, str):
            if id_a < id_b:
                return -1
            if id_a > id_b:
                return 1
        else:
            return -1 if isinstance(id_a, int) else 1

    if len_a == len_b:
        return 0
    return -1 if len_a < len_b else 1


def compare_versions(a: str, b: str) -> int:
    parsed_a = parse_version(a)
    parsed_b = parse_version(b)

    for i in range(3):
        x = parsed_a[i]
        y = parsed_b[i]
        if x < y:
            return -1
        if x > y:
            return 1

    pre_a = parsed_a[3]
    pre_b = parsed_b[3]

    if pre_a == pre_b:
        return 0
    if not pre_a:
        return 1
    if not pre_b:
        return -1

    return _compare_prerelease(pre_a, pre_b)


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, parse_version(v)) for v in versions]

    def key(item: tuple[str, tuple]) -> tuple:
        _, p = item
        return (p[0], p[1], p[2], p[3])

    parsed.sort(key=key)

    return [item[0] for item in parsed]
