import re
from decimal import Decimal, ROUND_HALF_EVEN

_PRICE_RE = re.compile(r'^[0-9]+(\.[0-9]{1,4})?$')


class FifoBook:
    def __init__(self):
        self._lots = []          # list of [remaining_qty, price_str, Decimal(price)]
        self._head = 0           # index of oldest non-empty lot
        self._holdings = 0       # total remaining qty
        self._realized = Decimal('0.00')

    def _validate_qty(self, qty):
        if type(qty) is not int:
            raise TypeError("qty must be int")
        if qty <= 0:
            raise ValueError("qty must be positive")

    def _validate_price(self, price):
        if type(price) is not str:
            raise TypeError("price must be str")
        if not _PRICE_RE.match(price):
            raise ValueError("invalid price format")

    def buy(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        dec_price = Decimal(price)
        self._lots.append([qty, price, dec_price])
        self._holdings += qty

    def sell(self, qty, price):
        self._validate_qty(qty)
        self._validate_price(price)
        if self._holdings < qty:
            raise ValueError("insufficient holdings")
        sell_price = Decimal(price)
        total_pnl = Decimal('0')
        remaining = qty
        while remaining > 0:
            lot = self._lots[self._head]
            consume = lot[0] if lot[0] <= remaining else remaining
            total_pnl += (sell_price - lot[2]) * consume
            lot[0] -= consume
            self._holdings -= consume
            remaining -= consume
            if lot[0] == 0:
                self._head += 1
        quantized = total_pnl.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        self._realized += quantized
        return quantized

    def realized(self):
        return self._realized

    def holdings(self):
        return self._holdings

    def lots(self):
        return [(lot[0], lot[1]) for lot in self._lots[self._head:]]

    def cost_basis(self):
        total = Decimal('0')
        for lot in self._lots[self._head:]:
            total += lot[2] * lot[0]
        return total.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
