def _validate_price(value):
    if value is None:
        return
    if isinstance(value, bool):
        raise TypeError("bool is not a valid price type")
    if isinstance(value, (int, float)):
        return
    raise TypeError("price must be int, float, or None")


def spans(prices: list) -> list:
    result = []
    stack = []  # indices with decreasing prices, no None indices
    for i, price in enumerate(prices):
        _validate_price(price)
        if price is None:
            result.append(0)
            stack.clear()
            continue
        while stack and prices[stack[-1]] > price:
            stack.pop()
        if stack:
            span = i - stack[-1]
        else:
            span = i + 1
        result.append(span)
        stack.append(i)
    return result


def next_greater(prices: list) -> list:
    n = len(prices)
    result = [-1] * n
    stack = []  # indices with decreasing prices, no None indices
    for i in range(n - 1, -1, -1):
        price = prices[i]
        _validate_price(price)
        if price is None:
            stack.clear()
            continue
        while stack and prices[stack[-1]] <= price:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        stack.append(i)
    return result


def widest_span(prices: list) -> tuple:
    span_values = spans(prices)
    best_index = -1
    best_span = 0
    for i, span in enumerate(span_values):
        if span >= best_span:
            best_index = i
            best_span = span
    return (best_index, best_span)
