def _parse_version(version: str) -> tuple[int, ...]:
    s = version.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split(".")
    result = []
    for part in parts:
        if not part or not part.isdigit():
            raise ValueError(f"invalid version part: {part!r}")
        # isdigit() rejects negative signs and letters
        result.append(int(part))
    return tuple(result)


def _compare_versions(a: tuple[int, ...], b: tuple[int, ...]) -> int:
    max_len = max(len(a), len(b))
    for i in range(max_len):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _parse_spec(spec: str):
    s = spec.strip()
    if not s:
        return []
    clauses = s.split(",")
    predicates = []
    for clause in clauses:
        c = clause.strip()
        if not c:
            raise ValueError("empty clause")
        # Check two-character operators first to avoid ambiguity
        op = None
        version_str = None
        for candidate in ("==", "!=", ">=", "<=", "~="):
            if c.startswith(candidate):
                op = candidate
                version_str = c[len(candidate):].strip()
                break
        if op is None:
            for candidate in (">", "<"):
                if c.startswith(candidate):
                    op = candidate
                    version_str = c[len(candidate):].strip()
                    break
        if op is None:
            raise ValueError(f"no operator in clause: {c!r}")
        target = _parse_version(version_str)
        if op == "==":
            predicates.append(lambda v, t=target: _compare_versions(v, t) == 0)
        elif op == "!=":
            predicates.append(lambda v, t=target: _compare_versions(v, t) != 0)
        elif op == ">=":
            predicates.append(lambda v, t=target: _compare_versions(v, t) >= 0)
        elif op == "<=":
            predicates.append(lambda v, t=target: _compare_versions(v, t) <= 0)
        elif op == ">":
            predicates.append(lambda v, t=target: _compare_versions(v, t) > 0)
        elif op == "<":
            predicates.append(lambda v, t=target: _compare_versions(v, t) < 0)
        elif op == "~=":
            if len(target) < 2:
                raise ValueError("~= requires at least two version components")
            upper_parts = list(target[:-1])
            upper_parts[-1] += 1
            upper = tuple(upper_parts)
            predicates.append(
                lambda v, t=target, u=upper:
                _compare_versions(v, t) >= 0 and _compare_versions(v, u) < 0
            )
    return predicates


def satisfies(version: str, spec: str) -> bool:
    v = _parse_version(version)
    predicates = _parse_spec(spec)
    return all(predicate(v) for predicate in predicates)


def max_satisfying(versions: list[str], spec: str) -> str | None:
    parsed_versions = []
    for orig in versions:
        parsed_versions.append((orig, _parse_version(orig)))
    predicates = _parse_spec(spec)
    best_orig = None
    best_parsed = None
    for orig, v in parsed_versions:
        if all(predicate(v) for predicate in predicates):
            if best_parsed is None or _compare_versions(v, best_parsed) > 0:
                best_orig = orig
                best_parsed = v
            # If equal, keep the earlier one (do nothing)
    return best_orig
