def validate_stream(events):
    seen = set()
    prev = None
    for event in events:
        timestamp, event_id, payload = event
        if event_id in seen:
            raise ValueError(f"duplicate id {event_id!r}")
        seen.add(event_id)
        if prev is not None:
            prev_ts, prev_id, _ = prev
            if (timestamp, event_id) <= (prev_ts, prev_id):
                raise ValueError(f"unsorted at id {event_id!r}")
        prev = event


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)

    old_dict = {}
    for event in old:
        timestamp, event_id, payload = event
        old_dict[event_id] = event

    new_dict = {}
    new_order = []
    for event in new:
        timestamp, event_id, payload = event
        new_dict[event_id] = event
        new_order.append(event_id)

    old_ids = set(old_dict)
    new_ids = set(new_dict)

    added = [event_id for event_id in new_order if event_id not in old_ids]
    removed = [event_id for event_id in old_dict if event_id not in new_ids]
    moved = []
    changed = []

    for event_id in new_order:
        if event_id in old_ids:
            old_event = old_dict[event_id]
            new_event = new_dict[event_id]
            if old_event[0] != new_event[0]:
                moved.append(event_id)
            if old_event[2] != new_event[2]:
                changed.append(event_id)

    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)

    merged = {}
    for event in a:
        timestamp, event_id, payload = event
        merged[event_id] = event
    for event in b:
        timestamp, event_id, payload = event
        merged[event_id] = event

    result = sorted(merged.values(), key=lambda event: (event[0], event[1]))
    return result
