import heapq
from typing import Iterable, List, Tuple


class CycleError(ValueError):
    def __init__(self, nodes: List[str]):
        self.nodes = nodes
        super().__init__(f"cycle detected among nodes: {nodes}")


def _build_graph(nodes: Iterable[str], edges: List[Tuple[str, str]]):
    node_set = set(nodes)
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node {before!r}")
        if after not in node_set:
            raise ValueError(f"unknown node {after!r}")

    adjacency: dict[str, set[str]] = {node: set() for node in node_set}
    in_degree: dict[str, int] = {node: 0 for node in node_set}

    seen_edges = set()
    for before, after in edges:
        if (before, after) in seen_edges:
            continue
        seen_edges.add((before, after))
        adjacency[before].add(after)
        in_degree[after] += 1

    return node_set, adjacency, in_degree


def topo_order(nodes: Iterable[str], edges: List[Tuple[str, str]]) -> List[str]:
    node_set, adjacency, in_degree = _build_graph(nodes, edges)

    heap = [node for node in node_set if in_degree[node] == 0]
    heapq.heapify(heap)

    result: List[str] = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for neighbor in adjacency[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(node_set):
        remaining = sorted(node_set - set(result))
        raise CycleError(remaining)

    return result


def layers(nodes: Iterable[str], edges: List[Tuple[str, str]]) -> List[List[str]]:
    node_set, adjacency, in_degree = _build_graph(nodes, edges)

    current_layer = sorted(node for node in node_set if in_degree[node] == 0)
    result: List[List[str]] = []
    placed = set()

    while current_layer:
        result.append(current_layer)
        placed.update(current_layer)

        next_candidates: set[str] = set()
        for node in current_layer:
            for neighbor in adjacency[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    next_candidates.add(neighbor)

        current_layer = sorted(next_candidates)

    if len(placed) != len(node_set):
        remaining = sorted(node_set - placed)
        raise CycleError(remaining)

    return result
